  let mut groups=BTreeMap::<(usize,i64),Vec<&SqliteRow>>::new();for table in[12,14,16]{native.charge(read.tables[table].rows.len().checked_mul(144).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Wires relationship lookup overflow"))?)?;native.scoped_stage(|native|{native.begin_stage(read.tables[table].rows.len())?;for row in&read.tables[table].rows{native.step()?;groups.entry((table,row.integer(1)?)).or_default().push(row);}Ok::<(),ValueError>(())})?;}
  struct Plan<'a>{id:i64,kind:&'a str,row:&'a SqliteRow,relations:Vec<&'a SqliteRow>,children:Vec<i64>}
  let mut pending=native.allocate_vec::<i64>(read.tables[1].rows.len())?;if read.tables[1].rows.len()<2{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Wires two intrinsic roots are missing"))}pending.extend([meta_key,fixture_key]);let mut plans=native.allocate_vec::<Plan>(read.tables[1].rows.len())?;
  while let Some(id)=pending.pop(){let header=read.take(1,id,&mut native)?;let kind=header.text(1)?;let table=match kind{"null"=>5,"boolean"=>6,"unsigned"=>7,"signed"=>8,"float"=>9,"text"=>10,"bytes"=>11,"array"=>13,"object"=>15,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Wires intrinsic variant differs"))};let row=read.take(table,id,&mut native)?;let edge=match kind{"bytes"=>Some(12),"array"=>Some(14),"object"=>Some(16),_=>None};let mut children=Vec::new();let relations=if let Some(table)=edge{let rows=groups.remove(&(table,id)).unwrap_or_default();let rows=ordered(&rows,&mut native)?;children=native.allocate_vec::<i64>(if kind=="bytes"{0}else{rows.len()})?;for relation in&rows{read.take(table,relation.rowid,&mut native)?;if kind!="bytes"{children.push(relation.integer(if kind=="object"{4}else{3})?);}}rows}else{Vec::new()};if pending.len().checked_add(children.len()).and_then(|count|count.checked_add(plans.len())).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Wires frontier count overflow"))?>read.tables[1].rows.len(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Wires frontier exceeds owned values"))}pending.extend(children.iter().rev().copied());plans.push(Plan{id,kind,row,relations,children});}
  if read.used.len()!=total{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Wires has unowned entity rows"))}native.begin_stage(plans.len())?;let mut forest=Forest(native.allocate_vec::<Option<semio_framework_value::DslValue>>(plans.len())?);forest.0.resize_with(plans.len(),||None);native.charge(plans.len().checked_mul(48).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Wires topology lookup overflow"))?)?;let mut indices=BTreeMap::new();native.scoped_stage(|native|{native.begin_stage(plans.len())?;for(index,plan)in plans.iter().enumerate(){native.step()?;indices.insert(plan.id,index);}Ok::<(),ValueError>(())})?;
